const input = $input.all()[0].json;
if (!input.companies || !Array.isArray(input.companies) || input.companies.length === 0) {
  throw new Error('Input muss "companies" Array enthalten');
}
for (const company of input.companies) {
  if (!company.name) throw new Error('Jede Company braucht einen "name"');
  if (!company.target_titles || company.target_titles.length === 0) {
    throw new Error(`Company "${company.name}" braucht "target_titles"`);
  }
}

return input.companies.map(c => ({
  json: { company: c }
}));

const html = $input.all()[0].json.data || $input.all()[0].json.body || '';
const companyData = $input.all()[0].json.company || $('Split Companies').first().json.company;

const metaMatch = html.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["']/i);
const description = metaMatch ? metaMatch[1] : String(html).replace(/<[^>]+>/g, ' ').substring(0, 500).trim();

const techKeywords = ['oracle', 'aws', 'azure', 'cloud', 'saas', 'api', 'database', 'kubernetes', 'docker', 'java', '.net', 'python', 'microservices', 'iot', 'ai', 'machine learning'];
const htmlLower = String(html).toLowerCase();
const foundTech = techKeywords.filter(kw => htmlLower.includes(kw));

const industryKeywords = ['manufacturing', 'finance', 'insurance', 'healthcare', 'logistics', 'retail', 'energy', 'automotive', 'pharma', 'medtech', 'security', 'banking'];
const foundIndustry = industryKeywords.filter(kw => htmlLower.includes(kw));

return [{
  json: {
    company: {
      ...companyData,
      description,
      tech_stack_indicators: foundTech,
      industry_indicators: foundIndustry,
      analyzed_at: new Date().toISOString()
    }
  }
}];

const company = $input.all()[0].json.company;

return company.target_titles.map(title => ({
  json: {
    search_query: `${title} ${company.name}`,
    company_name: company.name,
    target_title: title,
    company_data: company
  }
}));

const results = $input.all()[0].json;
const companyData = $('Build Phantombuster Searches').first().json.company_data;
const targetTitle = $('Build Phantombuster Searches').first().json.target_title;

let profiles = [];
try {
  const outputRaw = results.output || results.data || '[]';
  const output = typeof outputRaw === 'string' ? JSON.parse(outputRaw) : outputRaw;
  const arr = Array.isArray(output) ? output : [];
  profiles = arr
    .filter(p => p.name && p.profileUrl)
    .map(p => ({
      full_name: p.name,
      first_name: p.name.split(' ')[0],
      last_name: p.name.split(' ').slice(1).join(' '),
      linkedin_url: p.profileUrl,
      job_title: p.title || targetTitle,
      company_mentioned: p.companyName || companyData.name,
      location: p.location || '',
      headline: p.headline || ''
    }));
} catch (e) {
  profiles = [];
}

if (profiles.length === 0) return [];

return profiles.map(p => ({
  json: { profile: p, company_data: companyData }
}));

const items = $input.all();
const seen = new Set();
const unique = [];
for (const item of items) {
  const url = item.json.profile.linkedin_url;
  if (!seen.has(url)) {
    seen.add(url);
    unique.push(item);
  }
}
return unique.slice(0, 5);

const prospeoResult = $input.all()[0].json;
const profileNode = $('Deduplicate Profiles');
const profile = profileNode.first().json.profile;
const companyData = profileNode.first().json.company_data;

let email = null;
let emailConfidence = 0;

if (prospeoResult.response && prospeoResult.response.email) {
  email = prospeoResult.response.email;
  emailConfidence = prospeoResult.response.email_confidence || prospeoResult.response.confidence || 0;
}

if (!email) return [];

return [{
  json: {
    profile: { ...profile, email, email_confidence: emailConfidence, email_source: 'prospeo' },
    company_data: companyData
  }
}];

const bouncerResult = $input.all()[0].json;
const prevData = $('Wait — Rate Limit Prospeo').first().json;
const profile = prevData.profile;
const companyData = prevData.company_data;

const status = bouncerResult.status || 'unknown';
const isValid = ['deliverable', 'risky'].includes(status);

return [{
  json: {
    profile: {
      ...profile,
      email_verified: isValid,
      email_status: status,
      email_reason: bouncerResult.reason || ''
    },
    company_data: companyData
  }
}];

const profile = $input.all()[0].json.profile;
const company = $input.all()[0].json.company_data;

let score = 0;
const details = {};

// 1. Tech-Stack Indikatoren (0-20)
const techScore = Math.min((company.tech_stack_indicators?.length || 0) * 4, 20);
score += techScore;
details.metrics = { score: techScore, reason: `${company.tech_stack_indicators?.length || 0} Tech-Indikatoren` };

// 2. Entscheider-Position (0-20)
const buyerTitles = ['ceo', 'cto', 'cfo', 'cio', 'vp', 'vice president', 'director', 'head of', 'geschäftsführer', 'vorstand', 'leiter'];
const titleLower = (profile.job_title || '').toLowerCase();
const isBuyer = buyerTitles.some(t => titleLower.includes(t));
const buyerScore = isBuyer ? 20 : (titleLower.includes('manager') ? 10 : 5);
score += buyerScore;
details.economic_buyer = { score: buyerScore, reason: profile.job_title };

// 3. Tech-Relevanz des Titels (0-15)
const techTitles = ['cloud', 'infrastructure', 'platform', 'data', 'digital', 'transformation', 'it ', 'technology', 'engineering', 'development', 'software'];
const techRelevance = techTitles.filter(t => titleLower.includes(t)).length;
const dcScore = Math.min(techRelevance * 5, 15);
score += dcScore;
details.decision_criteria = { score: dcScore, reason: `${techRelevance} tech-Keywords im Titel` };

// 4. Email Confidence (0-15)
const emailConfScore = profile.email_confidence > 90 ? 15 : (profile.email_confidence > 70 ? 10 : 5);
score += emailConfScore;
details.decision_process = { score: emailConfScore, reason: `Email Confidence: ${profile.email_confidence}%` };

// 5. Industrie-Relevanz (0-15)
const oracleIndustries = ['finance', 'insurance', 'banking', 'manufacturing', 'logistics', 'healthcare', 'energy', 'retail', 'automotive'];
const industryMatch = (company.industry_indicators || []).filter(i => oracleIndustries.includes(i)).length;
const painScore = Math.min(industryMatch * 5, 15);
score += painScore;
details.identify_pain = { score: painScore, reason: `${industryMatch} relevante Branchen` };

// 6. LinkedIn Headline (0-15)
const championScore = profile.headline?.length > 50 ? 15 : (profile.headline?.length > 20 ? 10 : 5);
score += championScore;
details.champion = { score: championScore, reason: `Headline ${profile.headline?.length || 0} Zeichen` };

let category;
if (score >= 70) category = 'HOT';
else if (score >= 45) category = 'WARM';
else category = 'COLD';

return [{
  json: {
    profile: { ...profile, meddic_score: score, meddic_category: category, meddic_details: details },
    company_data: company
  }
}];

