const aiResponse = $input.all()[0].json;
const prevData = $('MEDDIC Scoring').first().json;

let analyse = 'Analyse nicht verfügbar';
try {
  if (aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message) {
    analyse = aiResponse.choices[0].message.content.trim();
  }
} catch (e) {
  analyse = 'Fehler bei AI-Analyse: ' + e.message;
}

return [{
  json: {
    profile: { ...prevData.profile, ai_analyse: analyse },
    company_data: prevData.company_data
  }
}];

const data = $input.all()[0].json;
const p = data.profile;
const c = data.company_data;

return [{
  json: {
    Firma: c.name || '',
    Website: c.website || '',
    Branche: (c.industry_indicators || []).join(', '),
    'Tech-Stack': (c.tech_stack_indicators || []).join(', '),
    Vorname: p.first_name || '',
    Nachname: p.last_name || '',
    Position: p.job_title || '',
    'LinkedIn URL': p.linkedin_url || '',
    Headline: p.headline || '',
    Standort: p.location || '',
    Email: p.email || '',
    'Email Verifiziert': p.email_verified ? 'Ja' : 'Nein',
    'Email Status': p.email_status || '',
    'Email Confidence': p.email_confidence || '',
    'MEDDIC Score': p.meddic_score || 0,
    'MEDDIC Kategorie': p.meddic_category || '',
    'Personen-Analyse': p.ai_analyse || '',
    Zeitstempel: new Date().toISOString()
  }
}];

const items = $input.all();
const count = items.length;

return [{
  json: {
    status: 'completed',
    message: `${count} Leads erfolgreich in Google Sheets eingetragen.`,
    timestamp: new Date().toISOString()
  }
}];
